package com.ferreteriahuaman.repository;
import com.ferreteriahuaman.dto.SaleModels.*;import com.ferreteriahuaman.dto.CatalogModels.Page;import java.sql.*;import java.time.*;import java.math.BigDecimal;import java.util.*;import org.springframework.context.annotation.Profile;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository @Profile("db") public class SaleRepository {
 private final JdbcTemplate jdbc;public SaleRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
 private Map<String,Object> row(ResultSet r,int n)throws SQLException{var map=new LinkedHashMap<String,Object>();var meta=r.getMetaData();for(int i=1;i<=meta.getColumnCount();i++){Object v=r.getObject(i);if(v instanceof BigDecimal d)v=d.toPlainString();else if(v instanceof Timestamp t)v=t.toLocalDateTime().toString();else if(v instanceof UUID u)v=u.toString();map.put(meta.getColumnLabel(i),v);}return map;}
 public Optional<Map<String,Object>> get(long id,boolean lock){return jdbc.query("select v.id_venta id,v.id_caja \"cajaId\",v.id_vendedor \"vendedorId\",v.id_cotizacion \"cotizacionId\",(select vigente_hasta::text from huaman.cotizacion where id_cotizacion=v.id_cotizacion) \"cotizacionVigenteHasta\",v.clave_idempotencia clave,v.tipo_comprobante tipo,v.id_cliente \"clienteId\",v.cliente_nombre cliente,(select username from huaman.usuario where id_usuario=v.id_vendedor) vendedor,v.cliente_nro_doc documento,v.cliente_direccion direccion,v.entrega_inmediata \"entregaInmediata\",v.id_venta_origen \"origenId\",v.motivo_anulacion \"motivoAnulacion\",v.fecha_anulacion \"fechaAnulacion\",(select estado_despacho from huaman.despacho where id_venta=v.id_venta) \"despachoEstado\",v.subtotal,v.descuento_total descuento,v.total,v.base_imponible base,v.igv,v.igv_porcentaje \"igvPorcentaje\",v.fecha_venta fecha,case when v.estado='I' then 'DESCARTADA' else v.estado_venta end estado,coalesce(v.fecmod,v.feccre) version from huaman.venta v where v.id_venta=?"+(lock?" for update of v":""),this::row,id).stream().findFirst();}
 public List<Map<String,Object>> drafts(long actor){return jdbc.query("select id_venta id,fecha_venta fecha,cliente_nombre cliente,total from huaman.venta where id_vendedor=? and estado='A' and estado_venta='BORRADOR' order by id_venta desc limit 100",this::row,actor);}
 public List<Map<String,Object>> lines(long id){return jdbc.query("select d.id_detalle_venta id,d.id_producto \"productoId\",d.id_presentacion \"presentacionId\",d.producto_nombre producto,d.presentacion_nombre presentacion,d.unidad_base_simbolo unidad,d.cantidad,d.cantidad_base \"cantidadBase\",d.factor_base factor,d.piezas_solicitadas piezas,d.longitud_pieza_base \"longitudPieza\",d.precio_lista \"precioLista\",d.precio_unitario precio,d.origen_precio origen,d.descuento_monto descuento,d.importe,p.modo_control \"modoControl\" from huaman.detalle_venta d join huaman.producto p using(id_producto) where d.id_venta=? and d.estado='A' order by d.id_detalle_venta",this::row,id);}
 public List<Map<String,Object>> payments(long id){return jdbc.query("select medio,monto,monto_recibido recibido,vuelto,nro_operacion operacion,marca_tarjeta marca,ultimos_cuatro \"ultimosCuatro\" from huaman.pago where id_venta=? and estado='A' order by id_pago",this::row,id);}
 public Map<String,Object> receipt(long id){return jdbc.query("select id_comprobante id,tipo_comprobante tipo,serie,numero,fecha_emision fecha,cliente_tipo_doc \"tipoDocumento\",cliente_nro_doc documento,cliente_nombre cliente,cliente_direccion direccion,negocio_nombre negocio,negocio_ruc ruc,negocio_direccion \"direccionNegocio\",negocio_telefono telefono,estado_comprobante estado,formato,mensaje_final mensaje,base_imponible base,igv,total,estado_tributario \"estadoTributario\" from huaman.comprobante_venta where id_venta=?",this::row,id).stream().findFirst().orElse(null);}
 public List<Map<String,Object>> series(){return jdbc.query("select id_serie id,tipo_comprobante tipo,serie from huaman.serie_comprobante where estado='A' order by tipo_comprobante,serie",this::row);}
 public boolean fiscalReady(){return Boolean.TRUE.equals(jdbc.queryForObject("select coalesce((select valor ~ '^[0-9]{11}$' and valor<>'00000000000' from huaman.parametro_sistema where clave='NEGOCIO.RUC' and estado='A'),false) and coalesce((select length(btrim(valor))>=5 from huaman.parametro_sistema where clave='NEGOCIO.DIRECCION' and estado='A'),false)",Boolean.class));}
 public void lockCash(long id){jdbc.queryForObject("select id_caja from huaman.caja_diaria where id_caja=? for update",Long.class,id);}
 public long create(long caja,long actor,Create i){return jdbc.queryForObject("insert into huaman.venta(id_caja,id_vendedor,id_cliente,tipo_comprobante,entrega_inmediata,clave_idempotencia,igv_porcentaje) values(?,?,?,?,?,?,(select valor::numeric from huaman.parametro_sistema where clave='VENTAS.IGV_PORC' and estado='A')) returning id_venta",Long.class,caja,actor,i.clienteId(),i.tipo(),i.entregaInmediata(),i.clave());}
 public void add(long sale,Line l){jdbc.update("insert into huaman.detalle_venta(id_venta,id_producto,id_presentacion,cantidad,piezas_solicitadas) select ?,id_producto,id_presentacion,?,? from huaman.presentacion_producto where id_presentacion=?",sale,l.cantidad(),l.piezas(),l.presentacionId());}
 public void payment(long id,Payment p){jdbc.update("insert into huaman.pago(id_venta,medio,monto,monto_recibido,vuelto,nro_operacion,marca_tarjeta,ultimos_cuatro) values(?,?,?,?,?,?,?,?)",id,p.medio(),p.monto(),p.recibido(),p.recibido()==null?null:p.recibido().subtract(p.monto()),p.operacion(),p.marca(),p.ultimosCuatro());}
 public long confirm(long id,long serie,UUID key,String assignments){return jdbc.queryForObject("select huaman.confirmar_venta(?,?,?,?::jsonb)",Long.class,id,serie,key,assignments);}
 public void discard(long id,Discard i){jdbc.queryForObject("select huaman.descartar_venta(?,?,?)",Long.class,id,i.clave(),i.motivo());}
 public void lockKey(UUID key){jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,"POS:"+key);}
 public Optional<Long> replay(String action,String reference,long actor,String request){var rows=jdbc.queryForList("select id_entidad,id_usuario=? and valor_nuevo->'solicitud'=?::jsonb valid from huaman.bitacora_evento where accion=? and referencia=?",actor,request,action,reference);if(rows.isEmpty())return Optional.empty();if(rows.size()!=1||!Boolean.TRUE.equals(rows.getFirst().get("valid")))throw new com.ferreteriahuaman.security.AuthFailure(409,"La solicitud ya se usó con otros datos");return Optional.of(((Number)rows.getFirst().get("id_entidad")).longValue());}
 public void audit(long actor,String action,long id,String reference,String request){jdbc.update("insert into huaman.bitacora_evento(id_usuario,accion,entidad,id_entidad,referencia,valor_nuevo) values(?,?,'venta',?,?,jsonb_build_object('solicitud',?::jsonb))",actor,action,id,reference,request);}
 public Page<Map<String,Object>> units(long sale,long line,int page){String from=" from huaman.unidad_existencia u join huaman.detalle_venta d on d.id_producto=u.id_producto where d.id_venta=? and d.id_detalle_venta=? and d.estado='A' and u.estado='A' and u.cantidad_disponible_base>0";long count=jdbc.queryForObject("select count(*)"+from,Long.class,sale,line);return new Page<>(jdbc.query("select u.id_unidad_existencia id,u.identificador,u.condicion_fisica condicion,u.cantidad_disponible_base cantidad,u.id_presentacion \"presentacionId\""+from+" order by u.id_unidad_existencia limit 20 offset ?",this::row,sale,line,(long)page*20),count,page,20);}

 public Page<Map<String,Object>> history(String q,LocalDate fromDate,LocalDate toDate,String type,String state,Long seller,int page,int size){String e=Character.toString(92),pattern="%"+q.replace(e,e+e).replace("%",e+"%").replace("_",e+"_")+"%";String from=" from huaman.venta v join huaman.usuario u on u.id_usuario=v.id_vendedor left join huaman.comprobante_venta c using(id_venta) ",filter="where v.estado='A' and v.estado_venta in ('CONFIRMADA','ANULADA') and (?::date is null or v.fecha_venta>=?::date) and (?::date is null or v.fecha_venta<(?::date+1)) and (?='' or v.tipo_comprobante=?) and (?='' or v.estado_venta=?) and (?::bigint is null or v.id_vendedor=?) and (v.cliente_nombre ilike ? or coalesce(v.cliente_nro_doc,'') ilike ? or v.id_venta::text ilike ? or (c.serie||'-'||lpad(c.numero::text,8,'0')) ilike ?)";Object[] args={fromDate,fromDate,toDate,toDate,type,type,state,state,seller,seller,pattern,pattern,pattern,pattern};long count=jdbc.queryForObject("select count(*)"+from+filter,Long.class,args);var params=new ArrayList<Object>(Arrays.asList(args));params.add(size);params.add((long)page*size);return new Page<>(jdbc.query("select v.id_venta id,v.fecha_venta fecha,v.cliente_nombre cliente,v.cliente_nro_doc documento,u.username vendedor,v.tipo_comprobante tipo,v.total,v.estado_venta estado,c.serie,c.numero,(select string_agg(distinct medio,', ' order by medio) from huaman.pago where id_venta=v.id_venta and estado='A') medios"+from+filter+" order by v.fecha_venta desc,v.id_venta desc limit ? offset ?",this::row,params.toArray()),count,page,size);}
 public List<Map<String,Object>> sellers(){return jdbc.query("select distinct u.id_usuario id,u.username nombre from huaman.usuario u join huaman.venta v on v.id_vendedor=u.id_usuario where v.estado='A' and v.estado_venta in ('CONFIRMADA','ANULADA') order by u.username",this::row);}
 public long copy(long caja,long actor,long source,Create i){return jdbc.queryForObject("insert into huaman.venta(id_caja,id_vendedor,id_cliente,id_venta_origen,tipo_comprobante,entrega_inmediata,clave_idempotencia,igv_porcentaje) values(?,?,?,?,?,false,?,(select valor::numeric from huaman.parametro_sistema where clave='VENTAS.IGV_PORC' and estado='A')) returning id_venta",Long.class,caja,actor,i.clienteId(),source,i.tipo(),i.clave());}
 public void cancel(long id,UUID key,String reason,boolean returned,String units,String references){jdbc.queryForObject("select huaman.anular_venta(?,?,?, ?,?::jsonb,?::jsonb)",Long.class,id,key,reason,returned,units,references);}
}
